<script lang="ts">
  import {command} from './api';
  import {createRequestGate} from './requestGate.js';
  import {macroKey,validateMacro,appendRecordedAction,importMacroFile,macroKeyOptions,stopRecordingWithKey} from './macroDraft.js';
  import {onDestroy} from 'svelte';
  interface Action {kind:'key'|'modifier'|'mouse';state:'down'|'up';code:number;delayMs:number}
  interface Snapshot {deviceId:string;model:string;slot:number;stateToken:string;editable:boolean;actions:Action[];maxActions:number;buttons:{id:string;rawHex:string}[]}
  let {deviceId,active=true}:{deviceId:string|null;active?:boolean}=$props();
  let snapshot=$state<Snapshot|null>(null);let actions=$state<Action[]>([]);let slot=$state(0);let busy=$state(false);let recording=$state(false);let error=$state('');let success=$state('');let confirmed=$state(false);let target=$state('side1');let repeat=$state(1);let loadedId='';let area=$state<HTMLTextAreaElement>();let lastTime=0;let pressed=new Map<string,{kind:Action['kind'];code:number}>();const requests=createRequestGate();
  const dirty=$derived(!!snapshot&&JSON.stringify(actions)!==JSON.stringify(snapshot.actions));
  const invalid=$derived.by(()=>{try{validateMacro(actions,snapshot?.maxActions??70);return '';}catch(e){return message(e);}});
  const message=(e:unknown)=>e&&typeof e==='object'&&'message'in e?String(e.message):String(e);
  function accept(value:Snapshot){snapshot=value;actions=value.actions.map(a=>({...a}));confirmed=true;}
  async function read(){if(!deviceId||busy)return;const current=requests.begin();busy=true;error='';success='';try{const value=await command<Snapshot>('read_atk_macro',{deviceId,slot});if(current())accept(value);}catch(e){if(current()){error=message(e);confirmed=false;}}finally{if(current())busy=false;}}
  async function write(bind=false){if(!deviceId||!snapshot||busy||recording||!confirmed||!snapshot.editable||invalid||(!bind&&!dirty)||(bind&&(dirty||!actions.length||!Number.isInteger(repeat)||repeat<1||repeat>250)))return;const current=requests.begin();busy=true;error='';success='';try{const change=bind?{slot,buttonId:target,repeat,expectedState:snapshot.stateToken}:{slot,actions:validateMacro(actions,snapshot.maxActions),expectedState:snapshot.stateToken};const value=await command<Snapshot>(bind?'bind_atk_macro':'apply_atk_macro',{deviceId,change});if(current()){accept(value);success=bind?'宏绑定已写入并读回确认。':'宏动作已写入并读回确认。';}}catch(e){if(current()){error=`${message(e)}。请重新读取核对。`;confirmed=false;}}finally{if(current())busy=false;}}
  function start(){if(dirty&&!window.confirm('开始录制会替换尚未写入的宏预览，是否继续？'))return;recording=true;actions=[];pressed.clear();lastTime=performance.now();error='';success='';area?.focus();}
  function stop(){if(!recording)return;const now=performance.now();for(const value of pressed.values())lastTime=appendRecordedAction(actions,{...value,state:'up'},now,lastTime);pressed.clear();recording=false;}
  function capture(e:KeyboardEvent,state:'down'|'up'){if(!recording)return;if(stopRecordingWithKey(e,stop))return;e.preventDefault();e.stopPropagation();if(e.repeat)return;const value=macroKey(e.code);if(!value){error=`未记录不支持的键：${e.code}`;return;}if(state==='up'&&!pressed.has(e.code))return;if(state==='down'&&pressed.has(e.code))return;
    // Reserve one release action for every held key, so stopping cannot leave keys down.
    const held=pressed.size+(state==='down'?1:-1);if(actions.length+1+held>(snapshot?.maxActions??70)){stop();error='已达到动作容量，录制已停止并补齐按键抬起。';return;}
    lastTime=appendRecordedAction(actions,{...value,state},performance.now(),lastTime);if(state==='down')pressed.set(e.code,value as {kind:Action['kind'];code:number});else pressed.delete(e.code);
  }
  async function importFile(e:Event){const input=e.currentTarget as HTMLInputElement;const file=input.files?.[0];if(!file||busy||recording)return;if(dirty&&!window.confirm('导入会替换尚未写入的宏预览，是否继续？')){input.value='';return;}const current=requests.begin();busy=true;error='';success='';try{if(file.size>100000)throw new Error('文件过大。');const value=await importMacroFile(file,current,snapshot?.maxActions??70);if(value&&current()){actions=value as Action[];success='已导入本地预览，尚未写入设备。';}}catch(e){if(current())error=message(e);}finally{input.value='';if(current())busy=false;}}
  function download(){try{const value=validateMacro(actions,snapshot?.maxActions??70);const url=URL.createObjectURL(new Blob([JSON.stringify({version:1,actions:value},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`atk-macro-${slot+1}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){error=message(e);}}
  function changeSlot(e:Event){slot=Number((e.currentTarget as HTMLSelectElement).value);snapshot=null;void read();}
  function changeKind(item:Action,e:Event){item.kind=(e.currentTarget as HTMLSelectElement).value as Action['kind'];item.code=macroKeyOptions(item.kind)[0].code;}
  export function hasUnsavedChanges(){return dirty||busy||recording;}export function isOperationPending(){return busy||recording;}
  $effect(()=>{if(!active)stop();});
  $effect(()=>{if(loadedId!==(deviceId||'')){loadedId=deviceId||'';stop();requests.invalidate();snapshot=null;actions=[];busy=false;confirmed=false;if(deviceId)void read();}});
  onDestroy(()=>requests.invalidate());
</script>
<div class="macro-heading"><h3>快捷指令录制</h3><p>选择宏槽，编辑动作序列，再写入并绑定到鼠标按键。</p></div>
<p class="settings-intro">仅采集输入区内的按键。Escape 停止录制，Tab 停止并移到下一控件；这两个键可通过“添加动作”手动加入宏。</p>
<div class="setting-field"><label for="macro-slot">宏槽</label><select id="macro-slot" value={slot} disabled={busy||dirty||recording} onchange={changeSlot}>{#each Array.from({length:12},(_,i)=>i) as i}<option value={i}>宏 {i+1}</option>{/each}</select></div>
{#if snapshot}
{#if !snapshot.editable}<p class="settings-intro">设备原宏格式尚未识别，当前槽保持只读；本地预览可导出，不会覆盖设备。</p>{/if}
<div class="macro-toolbar"><button class="secondary" disabled={busy||recording||!snapshot.editable} onclick={start}>开始录制（替换预览）</button><button class="secondary" disabled={!recording} onclick={stop}>停止录制</button><label class="secondary file-label">导入 JSON<input type="file" accept=".json,application/json" disabled={busy||recording} onchange={importFile}/></label><button class="secondary" disabled={recording||!!invalid} onclick={download}>导出预览</button><button class="secondary" disabled={busy||recording||!actions.length} onclick={()=>actions=[]}>清空预览</button></div>
<label class="mapping-label" for="macro-record">{recording?'正在录制 · Escape 或 Tab 停止':'录制输入区'}</label><textarea id="macro-record" bind:this={area} readonly value={recording?'正在录制，按 Escape 停止，按 Tab 离开':'点击开始录制后，在此按下需要的组合键'} onkeydown={e=>capture(e,'down')} onkeyup={e=>capture(e,'up')} onblur={stop} disabled={busy}></textarea>
<p class="settings-intro">{actions.length} / {snapshot.maxActions} 条动作。选择按键名称、按下/抬起和动作后延迟（毫秒）。停止时自动补齐未释放按键。</p>
<div class="macro-actions">{#each actions as item,i}<div class="macro-row"><span>{i+1}</span><select aria-label={`动作${i+1}类型`} value={item.kind} onchange={e=>changeKind(item,e)} disabled={busy||recording}><option value="key">键盘</option><option value="modifier">修饰键</option><option value="mouse">鼠标</option></select><select aria-label={`动作${i+1}状态`} bind:value={item.state} disabled={busy||recording}><option value="down">按下</option><option value="up">抬起</option></select><select aria-label={`动作${i+1}按键`} bind:value={item.code} disabled={busy||recording}>{#if !macroKeyOptions(item.kind).some(option=>option.code===item.code)}<option value={item.code} disabled>未知 {item.code}</option>{/if}{#each macroKeyOptions(item.kind) as option}<option value={option.code}>{option.label}</option>{/each}</select><label class="macro-delay">延迟 ms<input aria-label={`动作${i+1}延时毫秒`} title="延时（毫秒）" type="number" min="0" max="65535" bind:value={item.delayMs} disabled={busy||recording}/></label><button class="secondary" aria-label={`删除动作${i+1}`} disabled={busy||recording} onclick={()=>actions=actions.filter((_,j)=>j!==i)}>×</button></div>{/each}</div>
<button class="secondary" disabled={busy||recording||actions.length>=snapshot.maxActions} onclick={()=>actions.push({kind:'key',state:'down',code:4,delayMs:0})}>添加动作</button>
{#if invalid}<p class="message error" role="alert">{invalid}</p>{/if}
{#if dirty}<div class="change-preview"><strong>宏动作有本地修改</strong><p>导入、录制和编辑均为预览；点击写入后才更新设备。</p></div>{/if}
<section class="macro-binding" aria-label="将已保存的宏绑定到按钮"><h4>绑定已保存的宏</h4><p class="settings-intro">先写入并读回宏动作，再将当前宏绑定到一个按钮。</p><div class="macro-binding-fields"><div class="setting-field"><label for="macro-button">绑定到按钮</label><select id="macro-button" bind:value={target} disabled={busy||recording}>{#each snapshot.buttons as button}<option value={button.id}>{({left:'左键',right:'右键',center:'中键',side1:'侧键 1',side2:'侧键 2',bottom:'底部按键'} as Record<string,string>)[button.id]||button.id}</option>{/each}</select></div><div class="setting-field"><label for="macro-repeat">重复次数</label><input id="macro-repeat" type="number" min="1" max="250" bind:value={repeat} disabled={busy||recording}/></div></div><button class="secondary" disabled={dirty||busy||recording||!!invalid||!actions.length||!confirmed||!snapshot.editable||!Number.isInteger(repeat)||repeat<1||repeat>250} onclick={()=>write(true)}>绑定当前宏并读回</button></section>
{:else}<div class="settings-empty" role="status"><strong>{busy?'正在读取宏槽…':!deviceId?'连接鼠标后读取宏槽':'尚未取得宏槽内容'}</strong><p>设备读回后可录制、导入和编辑宏动作。</p></div>{/if}
{#if error}<p class="message error" role="alert">{error}</p>{/if}{#if success}<p class="settings-success" role="status">{success}</p>{/if}<div class="settings-actions"><span role="status">{recording?'正在录制，按 Escape 或 Tab 停止。':busy?'等待设备确认…':!confirmed&&dirty?'请先撤回预览再重新读取核对。':dirty?'宏动作仍为本地预览':''}</span><button class="secondary" disabled={!deviceId||busy||dirty||recording} onclick={read}>重新读取</button><button class="secondary" disabled={!dirty||busy||recording} onclick={()=>{if(snapshot){const wasConfirmed=confirmed;accept(snapshot);confirmed=wasConfirmed;}}}>撤回预览</button><button class="primary" disabled={!dirty||busy||recording||!!invalid||!confirmed||!snapshot?.editable} onclick={()=>write()}>{busy?'等待设备确认…':'写入宏槽并读回'}</button></div>
<style>
 .macro-heading h3{font-size:16px;font-weight:600;margin:0 0 8px}.macro-heading p{font-size:12px;line-height:1.65;color:var(--muted);margin:0 0 16px}.macro-toolbar{display:flex;flex-wrap:wrap;gap:8px;margin:24px 0 16px}.macro-toolbar button,.file-label{min-height:36px;font-size:12px}.macro-actions{container-type:inline-size;max-height:360px;overflow:auto;margin:16px 0;overscroll-behavior:contain}.macro-row{display:grid;grid-template-columns:24px 80px 72px minmax(104px,1fr) 96px 32px;gap:8px;align-items:end;padding:12px 0;border-bottom:1px solid var(--quiet-line);font-size:12px}.macro-row>span{align-self:center;color:var(--muted);font-variant-numeric:tabular-nums}.macro-row input,.macro-row select{min-width:0;width:100%;padding:8px;background:var(--control);color:var(--ink);border:1px solid var(--line);border-radius:8px;font:inherit;font-size:12px;min-height:36px}.macro-delay{display:flex;flex-direction:column;gap:4px;font-size:12px;color:var(--muted)}.macro-row button{padding:8px;min-height:36px;align-self:end}.file-label{display:inline-flex;align-items:center;position:relative;cursor:pointer}.file-label:focus-within{outline:2px solid var(--accent);outline-offset:2px}.file-label:has(input:disabled){opacity:.5;cursor:default}.file-label input{position:absolute;width:1px;height:1px;opacity:0}.mapping-label{display:block;font-size:13px;font-weight:500;margin-bottom:8px}textarea{display:block;width:100%;min-height:80px;resize:vertical;background:var(--control);border:1px solid var(--line);border-radius:12px;color:var(--ink);padding:12px;font:inherit;font-size:12px;line-height:1.65}textarea:focus-visible{outline:2px solid var(--accent);outline-offset:2px}.macro-binding{margin-top:24px;padding-top:24px;border-top:1px solid var(--quiet-line)}.macro-binding h4{font-size:14px;font-weight:600;margin:0 0 8px}.macro-binding-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:16px 0}.macro-binding-fields .setting-field{display:flex;flex-direction:column;align-items:stretch;gap:8px;padding:0!important;border:0}.macro-binding-fields label{font-size:13px}.macro-binding-fields select,.macro-binding-fields input{width:100%;min-width:0;min-height:36px;padding:8px 12px;font:inherit;font-size:12px;background:var(--control);color:var(--ink);border:1px solid var(--line);border-radius:8px}@container(max-width:600px){.macro-row{grid-template-columns:24px minmax(0,1fr) minmax(0,1fr) 32px;align-items:center}.macro-row>span{grid-column:1;grid-row:1}.macro-row select:nth-of-type(1){grid-column:2;grid-row:1}.macro-row select:nth-of-type(2){grid-column:3;grid-row:1}.macro-row select:nth-of-type(3){grid-column:2/4;grid-row:2}.macro-row .macro-delay{grid-column:2/4;grid-row:3;flex-direction:row;align-items:center;white-space:nowrap}.macro-row button{grid-column:4;grid-row:1}}@media(max-width:650px){.macro-binding-fields{grid-template-columns:1fr;gap:12px}}
</style>
